#include <vector>

using namespace std;

class Solution {
public:
    vector<int> transformArray(vector<int>& nums) {
        int evenCount = 0;
        for (int x : nums) {
            if (x % 2 == 0) evenCount++;
        }
        vector<int> ans(nums.size(), 1);
        for (int i = 0; i < evenCount; i++) {
            ans[i] = 0;
        }
        return ans;
    }
};

class Solution {
    public int[] transformArray(int[] nums) {
        int evenCount = 0;
        for (int x : nums) {
            if (x % 2 == 0) evenCount++;
        }
        int[] ans = new int[nums.length];
        for (int i = evenCount; i < nums.length; i++) {
            ans[i] = 1;
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
