var transformArray = function(nums) {
    let evenCount = 0;
    for (const x of nums) {
        if (x % 2 === 0) evenCount++;
    }
    const ans = new Array(nums.length).fill(1);
    for (let i = 0; i < evenCount; i++) {
        ans[i] = 0;
    }
    return ans;
};
